# SEGO Server one-command beginner installer.
# irm https://raw.githubusercontent.com/nadeemmhdm/sego-server/main/install.ps1 | iex
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;$Repo='nadeemmhdm/sego-server';$Tmp=Join-Path $env:TEMP ('sego-install-'+[guid]::NewGuid())
function Step([string]$t){Write-Host "`nSEGO $t" -ForegroundColor Cyan};function Fail([string]$t){throw "SEGO install error: $t"}
Step 'Server installer';Write-Host 'SEGO will download itself from GitHub, install required tools, configure automatic startup and guide first setup.';$a=Read-Host 'Continue? [Y/n]';if($a-match'^(n|no)$'){return}
New-Item -ItemType Directory -Force -Path $Tmp|Out-Null
try{Step 'Downloading SEGO from GitHub';$m=Invoke-RestMethod -Headers @{Accept='application/vnd.github+json'} -Uri "https://api.github.com/repos/$Repo/commits/main";$c=[string]$m.sha;if($c-notmatch'^[0-9a-f]{40}$'){Fail 'Could not resolve main commit'};$zip=Join-Path $Tmp 'sego.zip';Invoke-WebRequest -UseBasicParsing -Uri "https://github.com/$Repo/archive/$c.zip" -OutFile $zip;Expand-Archive $zip $Tmp -Force;$root=Join-Path $Tmp "sego-server-$c";$installer=Join-Path $root 'scripts\install.ps1';if(-not(Test-Path $installer)){Fail 'Downloaded installer is missing'};Step 'Starting guided setup';& $installer -Profile auto -Yes;if($LASTEXITCODE-ne 0){exit $LASTEXITCODE};& (Join-Path $root 'scripts\install-update-service.ps1');if($LASTEXITCODE-ne 0){exit $LASTEXITCODE};Write-Host "`nSEGO starts automatically whenever this computer boots." -ForegroundColor Green;Write-Host 'Automatic GitHub Release update checks are enabled.';Write-Host 'Open SEGO anytime with: sego open';$t=Read-Host 'Set up Cloudflare Tunnel remote access now? [y/N]';if($t-match'^(y|yes)$'){$sego=Join-Path $env:ProgramFiles 'SEGO\bin\sego.exe';Start-Process powershell.exe -Verb RunAs -Wait -ArgumentList @('-NoProfile','-NoExit','-Command',"& '$sego' tunnel setup; Write-Host ''; Read-Host 'Press Enter to close'")}}finally{Remove-Item $Tmp -Recurse -Force -ErrorAction SilentlyContinue}
